'use strict';
(() => {
const K='tju-research-v1', repo='Eternal-huang/-', el=id=>document.getElementById(id);
const papers=[
{id:'pei2022',stage:'入门',title:'Review of Operational Control Strategy for DC Microgrids with Electric-hydrogen Hybrid Storage Systems',meta:'Pei 等 · CSEE Journal of Power and Energy Systems · 2022 · 8(2): 329–346',type:'综述',keywords:'电氢储能 直流微网 能量管理 功率分配',url:'https://www.sciopen.com/article/10.17775/CSEEJPES.2021.06960',summary:'从电氢混合储能的运行控制框架入手，认识功率分配、设备动态与效率优化的关系。',questions:['画出储能、电解槽与电网之间的能量流向。','区分能量管理与快速控制，各自关注什么时间尺度？','哪些建模假设可以用于我们的简化模型？']},
{id:'dozein2023',stage:'核心',title:'Virtual Inertia Response and Frequency Control Ancillary Services From Hydrogen Electrolyzers',meta:'Dozein, De Corato & Mancarella · IEEE Transactions on Power Systems · 2023 · 38(3): 2447–2459',type:'期刊研究',keywords:'电解槽 调频 虚拟惯量 VSM PEM 碱性',url:'https://doi.org/10.1109/TPWRS.2022.3181853',summary:'研究电解槽动态模型及其频率支撑能力，涉及虚拟惯量、一次和二次频率响应，并讨论与电池储能的配合。',questions:['电解槽怎样通过改变用电功率支撑频率？','模型包含哪些设备动态与运行约束？','选择一个最简单的响应曲线，写出复现所需的模型和参数。']},
{id:'qiu2026',stage:'前沿',title:'Enhanced Hydrogen Electrolyzer with Integrated Energy Storage to Provide Grid-Forming Services for Off-Grid ReP2H Application',meta:'Qiu 等 · arXiv:2603.00514 · 2026',type:'预印本 · 未按期刊论文计',keywords:'构网 VSM 储能集成 SOC 分频 离网',url:'https://arxiv.org/abs/2603.00514',summary:'讨论储能集成电解槽的构网方案、不同时间尺度的协调支撑以及 SOC 均衡，可用于检查候选研究问题与已有工作的重叠。',questions:['离网构网场景与我们的目标场景有哪些差异？','文中哪些协调机制已经覆盖了我们的候选想法？','比较验证方式与模型精度，不直接照搬性能结论。']}
];
const templates={
reading:{tag:'阅读笔记',fields:[['problem','研究问题','作者具体解决什么问题？'],['method','模型与方法','主要结构、方程、控制逻辑与假设是什么？'],['evidence','证据与定位','记录图号、表号或页码，以及支撑结论的实验。'],['limits','局限与疑问','哪些条件尚未验证？有什么没看懂？'],['reproduce','复现计划','准备复现哪幅图？需要哪些参数、数据和模型？'],['connection','与本项目的关系','可借鉴什么？哪些想法已有研究，不能直接当成创新？']]},
question:{tag:'研究问题',fields:[['problem','具体问题','在什么条件下，什么现象需要解释或改进？'],['prior','已有工作','论文链接、已有方法及对应页码。'],['hypothesis','待验证假设','写成能通过实验检验或否定的陈述。'],['difference','候选差异','我们的改变是什么？尚未确认创新性时写明。'],['test','验证方式','如何设计对照，什么结果支持或否定假设？'],['help','需要的帮助','希望导师或组员判断什么？']]},
experiment:{tag:'实验记录',fields:[['status','计划或已完成','明确写“计划 / 运行中 / 已完成”，填写日期。'],['setup','模型与参数','模型版本、参数来源、单位、初始 SOC、仿真时长。'],['compare','工况与对照','扰动、基线、候选方法；公平比较如何保证？'],['metrics','指标与计算方式','频率偏差、RoCoF、恢复时间、SOC、制氢影响等。'],['results','结果与文件','真实结果、图表和数据链接；未运行写“待运行”。'],['limits','解释与下一步','能得出什么结论？异常、局限和下一步是什么？']]},
writing:{tag:'论文写作',fields:[['question','问题与定位','论文回答哪个具体问题？'],['related','相关工作与差异','最接近的研究及真实差异。'],['model','模型与方法','假设、方程、控制逻辑及适用边界。'],['evidence','已有证据','已经完成的实验、对应图表与数据链接。'],['missing','待补证据','哪些结论尚不能写，需要补什么实验？'],['outline','提纲与分工','章节安排、负责人、下一次审阅内容。']]}
};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={statuses:{},drafts:{}};try{const v=JSON.parse(localStorage.getItem(K));if(v&&v.statuses&&v.drafts&&typeof v.statuses==='object'&&typeof v.drafts==='object'&&!Array.isArray(v.drafts))data=v;}catch{}
const validStatuses=['待读','在读','已读','已复现'];let active='reading:pei2022';
const seedIds=new Set(papers.map(p=>p.id));
let catalogBusy=false;
function persist(){try{localStorage.setItem(K,JSON.stringify(data));el('draftState').textContent='已保存本机草稿 · '+new Date().toLocaleTimeString('zh-CN');}catch{el('draftState').textContent='本机保存失败，请立即导出 Markdown 备份。';}}
function key(){return el('recordType').value+':'+(el('recordType').value==='reading'?el('paperChoice').value:'default');}
function saveDraft(){const type=active.split(':')[0],d={author:el('recordAuthor').value,title:el('recordTitle').value,fields:{}};for(const [id] of templates[type].fields){const input=el('rf-'+id);if(input)d.fields[id]=input.value;}data.drafts[active]=d;persist();}
function loadDraft(){active=key();const type=el('recordType').value,d=data.drafts[active]||{};el('paperChoiceLabel').hidden=type!=='reading';el('recordAuthor').value=typeof d.author==='string'?d.author:'';el('recordTitle').value=typeof d.title==='string'?d.title:'';el('recordFields').innerHTML=templates[type].fields.map(([id,label,hint])=>`<label>${label}<textarea id="rf-${id}" maxlength="700" placeholder="${escape(hint)}">${escape(d.fields?.[id]||'')}</textarea></label>`).join('');el('draftState').textContent=data.drafts[active]?'已载入本机草稿':'草稿未填写';}
function renderPapers(){const q=el('paperSearch').value.trim().toLowerCase(),stage=el('paperStage').value;const list=papers.filter(p=>(stage==='all'||p.stage===stage)&&`${escape(p.title)} ${escape(p.meta)} ${p.keywords} ${escape(p.summary)}`.toLowerCase().includes(q));el('paperList').innerHTML=list.map(p=>`<article class="card paper-card"><div><span class="tag">${escape(p.stage)} · ${escape(p.type)}</span><h3>${escape(p.title)}</h3><div class="paper-meta">${escape(p.meta)}</div><p>${escape(p.summary)}</p><details><summary>带着这三个问题读</summary><ul>${p.questions.map(q=>`<li>${escape(q)}</li>`).join('')}</ul></details></div><div class="paper-actions"><a href="${escape(p.url)}" target="_blank" rel="noopener">${p.stage==='团队'?'打开 PDF ↗':'打开来源 ↗'}</a><label>本机阅读状态<select data-paper-status="${p.id}" aria-label="${p.id} 阅读状态">${validStatuses.map(s=>`<option ${data.statuses[p.id]===s?'selected':''}>${s}</option>`).join('')}</select></label><button data-note="${p.id}">写阅读笔记</button></div></article>`).join('')||'<div class="card">没有匹配的论文，请调整关键词或阶段筛选。</div>';}
function compose(type,paper){saveDraft();el('recordType').value=type;if(paper)el('paperChoice').value=paper;loadDraft();el('notebook').scrollIntoView({behavior:'smooth'});}
function markdown(){saveDraft();const type=el('recordType').value,d=data.drafts[active],paper=papers.find(p=>p.id===el('paperChoice').value);return `# [${templates[type].tag}] ${d.title.trim()||'未命名记录'}\n\n记录人：${d.author.trim()||'未填写'}\n日期：${new Date().toLocaleDateString('zh-CN')}\n`+(type==='reading'?`\n论文：${paper.title}\n来源：${paper.stage==='团队'?'https://github.com/'+repo+'/blob/main/papers/'+paper.url.slice(9):paper.url}\n类型：${paper.type}\n`:'')+templates[type].fields.map(([id,label])=>`\n## ${label}\n\n${d.fields[id]||'待补充'}\n`).join('');}
function download(text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));a.download=`research-${el('recordType').value}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
el('paperChoice').innerHTML=papers.map(p=>`<option value="${p.id}">${p.stage} · ${escape(p.title)}</option>`).join('');el('paperSearch').addEventListener('input',renderPapers);el('paperStage').addEventListener('change',renderPapers);el('paperList').addEventListener('change',e=>{const id=e.target.dataset.paperStatus;if(papers.some(p=>p.id===id)&&validStatuses.includes(e.target.value)){data.statuses[id]=e.target.value;persist();}});el('paperList').addEventListener('click',e=>{const id=e.target.dataset.note;if(id)compose('reading',id);});document.querySelectorAll('[data-compose]').forEach(b=>b.addEventListener('click',()=>compose(b.dataset.compose)));document.querySelectorAll('.research-link').forEach(a=>a.href=`https://github.com/${repo}/issues?q=${encodeURIComponent('is:issue '+a.dataset.query)}`);for(const id of ['recordType','paperChoice'])el(id).addEventListener('change',()=>{saveDraft();loadDraft();});for(const id of ['recordAuthor','recordTitle','recordFields'])el(id).addEventListener('input',saveDraft);
el('recordExport').addEventListener('click',()=>download(markdown()));el('recordCopy').addEventListener('click',async()=>{const text=markdown();try{await navigator.clipboard.writeText(text);el('draftState').textContent='已复制 Markdown，可粘贴到 GitHub 或笔记工具。';}catch{download(text);el('draftState').textContent='浏览器不允许复制，已导出 Markdown 文件。';}});
el('recordSubmit').addEventListener('click',()=>{if(!el('recordAuthor').value.trim()){el('recordAuthor').focus();el('draftState').textContent='请先填写记录人。';return;}if(!el('recordTitle').value.trim()){el('recordTitle').focus();el('draftState').textContent='请先填写记录标题。';return;}const text=markdown(),title=`[${templates[el('recordType').value].tag}] ${el('recordTitle').value.trim()}`,base=`https://github.com/${repo}/issues/new?title=${encodeURIComponent(title)}&body=`;let url=base+encodeURIComponent(text);if(url.length>7800){download(text);url=base+encodeURIComponent('请将刚下载的 Markdown 笔记内容粘贴在这里，再点击 Submit new issue。');el('draftState').textContent='笔记较长，已导出 Markdown；请将文件内容粘贴到 GitHub 提交页。';}else el('draftState').textContent='请在 GitHub 页面确认并点击 Submit new issue，才会共享给团队。';window.open(url,'_blank','noopener');});

renderPapers();loadDraft();
})();
